    <div class="form-grid" style="margin-top:8px"><?php field('title', 'Title (shown under the flyer)', ['value' => '']); field('subtitle', 'Small line (optional)', ['value' => '']); field('link', 'Link when tapped (optional, https://…)', ['value' => '']); field('starts_on', 'Starts on (optional)', ['type' => 'date', 'value' => '']); field('ends_on', 'Ends on (optional)', ['type' => 'date', 'value' => '']); ?></div>
