            <div class="form-grid"><?php field('title', 'Title', ['value' => $ad['title']]); field('subtitle', 'Small line', ['value' => $ad['subtitle']]); field('link', 'Link (https://…)', ['value' => (string)$ad['link']]); field('sort', 'Order (1 = first)', ['type' => 'number', 'value' => (string)$ad['sort']]); field('starts_on', 'Starts on', ['type' => 'date', 'value' => (string)$ad['starts_on']]); field('ends_on', 'Ends on', ['type' => 'date', 'value' => (string)$ad['ends_on']]); ?></div>
