            <button class="btn btn-primary btn-sm">Save</button></form></details></div>
      <div class="actions"><?php foreach (['toggle' => $ad['active'] ? 'Stop' : 'Run', 'delete' => 'Delete'] as $a => $l): ?><form class="inline" method="post" action="<?= url('admin/adverts') ?>"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $a ?>"><input type="hidden" name="id" value="<?= (int)$ad['id'] ?>"><button class="btn btn-ghost btn-sm"<?= $a === 'delete' ? ' onclick="return confirm(\'Delete this advert?\')"' : '' ?>><?= $l ?></button></form><?php endforeach; ?></div></div>
